{
  "implementation": "def solve(case):
    ref = case['refinement']
    edges = case['edges']
    members = {}
    for node, comm in ref.items():
        members.setdefault(comm, []).append(node)
    for comm in members:
        members[comm].sort()
    agg = {}
    for src, dst, w in edges:
        c1, c2 = ref[src], ref[dst]
        if c1 > c2:
            c1, c2 = c2, c1
        key = (c1, c2)
        agg[key] = agg.get(key, 0) + w
    agg_edges = [[c1, c2, total] for (c1, c2), total in agg.items()]
    agg_edges.sort(key=lambda x: (x[0], x[1]))
    return {'aggregate_edges': agg_edges, 'members': members}"
}
